candidates.pseudocode:
wedgeHeight = wedgeTopPrice - wedgeBottomPrice;
target1 = wedgeTopPrice; // test of the pattern's own top, for a long reversal out of a wedge bottom
target2 = wedgeTopPrice + wedgeHeight;
exitPartialLongAtTarget1 = high[0] >= target1;
exitRemainderLongAtTarget2 = high[0] >= target2

wedgeHeight = wedgeTopPrice - wedgeBottomPrice;
wedgeFailed = low[0] < (wedgeBottomPrice - failureTicks * tick); // for a wedge bottom that fails to hold as support
continuationTarget = wedgeBottomPrice - wedgeHeight;
exitShortAtTarget = low[0] <= continuationTarget

// research: 'exceptionally strong' has no bar-level definition in the text
allowFirstEntry = isThreePushPattern(UP, pivotStrength) && wedgeStrengthScore[0] >= exceptionalStrengthThreshold;
waitForSecondEntry = isThreePushPattern(UP, pivotStrength) && !allowFirstEntry

reversalDurationBars = currentBarIndex - patternStartBarIndex;
hasClearChannelLine = channelLineFitQuality(patternPivots) >= minChannelFitQuality;
isStrongReversalCandidate = reversalDurationBars >= minReversalBars && hasClearChannelLine

// research: 'tight channel' has no single stated bar-level test; candidate measures include high overlap(i) or small pullback-to-ATR ratio between pushes
isTightChannel = avgOverlapBetweenPushes(patternPivots) >= tightOverlapThreshold;
skipWedgeReversalEntry = isThreePushPattern(direction, pivotStrength) && isTightChannel

firstBreakout = swingHigh(1) - swingHigh(2) <= maxMinorBreakoutTicks * tick;
secondBreakout = swingHigh(0) - swingHigh(1) <= maxMinorBreakoutTicks * tick; // (evaluated once a new pivot forms)
thirdBreakoutConfirmsContinuation = close[0] > swingHigh(0);
enterLongOnThirdBreakout = firstBreakout && secondBreakout && thirdBreakoutConfirmsContinuation

doubleTopLevel = swingHigh(2); // the two prior highs forming the double top, within doubleTopTolTicks of each other
brokeAboveDoubleTop = high[k] > doubleTopLevel + entryTick for some k within lookbackBars;
failedBackBelow = close[0] < doubleTopLevel;
enterShortNextBarOpen = brokeAboveDoubleTop && failedBackBelow

// research: 'especially strong second push' has no bar-level definition
countLikelyReset = isThreePushPattern(direction, pivotStrength) && pushMomentumScore(push2) >= especiallyStrongThreshold;
requireFourthPushBeforeReversal = countLikelyReset;

// 'steep, tight' shares the undefined tightness measure from V05-10
isEarlySession = ctx.Time() <= sessionStart + openingWindowMinutes;
allowSteepWedgeReversal = isThreePushPattern(direction, pivotStrength) && isSteepTightWedge && isEarlySession;

// research: 'weak breakout' has no bar-level definition here
breakoutIsWeak = reversalBreakoutStrengthScore[0] < weakBreakoutThreshold;
tradeWithChannelInstead = isThreePushPattern(direction, pivotStrength) && breakoutIsWeak;

wedgeFailedThenReversedBack = wedgeFailed[withinBars] && (direction == UP ? close[0] > wedgeExtremePrice : close[0] < wedgeExtremePrice);
expectedTrendMinBars = 10;
expectedTrendMinLegs = 2;
